package edu.klh.soa.workflow;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/workflow")public class WorkflowController {private final ConsumedRepository repo;public WorkflowController(ConsumedRepository r){repo=r;}@GetMapping public List<ConsumedEvent> all(){return repo.findAll();}@GetMapping("/{eventId}")public ConsumedEvent one(@PathVariable String eventId){return repo.findById(eventId).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));}}